def mergeTwoLists(l1, l2):
    dummy = tail = ListNode(0)
    while l1 and l2:
        if l1.val <= l2.val:     # 取较小者
            tail.next, l1 = l1, l1.next
        else:
            tail.next, l2 = l2, l2.next
        tail = tail.next
    tail.next = l1 or l2         # 接上剩余
    return dummy.next

from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity):
        self.cap, self.od = capacity, OrderedDict()
    def get(self, key):
        if key not in self.od:
            return -1
        self.od.move_to_end(key)     # 提为最近使用
        return self.od[key]
    def put(self, key, value):
        if key in self.od:
            self.od.move_to_end(key)
        self.od[key] = value         # 写入或更新
        if len(self.od) > self.cap:
            self.od.popitem(last=False)  # 淘汰最旧

def getIntersectionNode(headA, headB):
    a, b = headA, headB
    while a is not b:
        a = a.next if a else headB  # 走完转对方
        b = b.next if b else headA
    return a                        # 交点或同 null

from collections import defaultdict, OrderedDict
class LFUCache:
    def __init__(self, cap):
        self.cap, self.minf, self.val = cap, 0, {}
        self.freq = defaultdict(OrderedDict)  # 频次分桶
    def _use(self, key):    # 频次加一并移桶
        self.val[key][1] += 1; f = self.val[key][1]; self.freq[f][key] = None; del self.freq[f-1][key]  # 移入新频桶
        if not self.freq[f-1] and self.minf == f-1: self.minf = f
    def get(self, key):
        if key not in self.val: return -1
        self._use(key); return self.val[key][0]
    def put(self, key, value):
        if key in self.val: self.val[key][0] = value; self._use(key); return
        if self.cap and len(self.val) == self.cap: k = self.freq[self.minf].popitem(last=False)[0]; del self.val[k]  # 淘汰最小频最旧
